const input = $input.first().json.metricData || $input.first().json;

// Procesamiento de métricas sin datos sensibles
const metricRecord = {
  operationId: input.operationId || 'met_' + Date.now(),
  workflowId: input.workflowId || 'unknown',
  correlationId: input.correlationId || 'unknown',
  executionTimeMs: input.executionTimeMs || 0,
  promptTokens: input.usage?.promptTokens || 0,
  completionTokens: input.usage?.completionTokens || 0,
  totalTokens: (input.usage?.promptTokens || 0) + (input.usage?.completionTokens || 0),
  model: input.usage?.model || 'unknown',
  status: input.status || 'completed',
  proposalsCount: input.proposalsCount || 0,
  humanReviewed: input.humanReviewed || false,
  humanAccepted: input.humanAccepted || false,
  recordedAt: new Date().toISOString()
};

return [{
  json: metricRecord
}];

const crypto = require('crypto');
const input = $input.first().json;
const secret = $env.RAX_N8N_SHARED_SECRET;
if (!secret) throw new Error('RAX_N8N_SHARED_SECRET is not configured');
const callbackPayload = {
  operationId: input.operationId || 'met_' + Date.now(),
  correlationId: input.correlationId || 'unknown',
  workflowId: 'RAX-15',
  workflowVersion: '1.0.0',
  status: 'completed',
  executionTimeMs: input.executionTimeMs || 0,
  usage: {
    model: input.model || 'unknown',
    promptTokens: input.promptTokens || 0,
    completionTokens: input.completionTokens || 0
  },
  data: { summary: 'Métrica operativa registrada para auditoría.' }
};
const timestamp = Math.floor(Date.now() / 1000).toString();
const callbackBody = JSON.stringify(callbackPayload);
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + callbackBody).digest('hex');
return [{ json: { ...input, callbackPayload, callbackBody, callbackTimestamp: timestamp, callbackSignature: signature, callbackCorrelationId: callbackPayload.correlationId } }];
